import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Applicant } from '../../types/app.types';
import { formatDateTimeArEg, formatDateToArabic } from './utils';

interface ApplicantDetailsDialogProps {
    isOpen: boolean;
    applicant: Applicant | null;
    onClose: () => void;
}

export default function ApplicantDetailsDialog({ isOpen, applicant, onClose }: ApplicantDetailsDialogProps) {
    return (
        <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
            <DialogContent dir="rtl" className="max-w-lg">
                <DialogHeader>
                    <DialogTitle className="text-right text-lg font-semibold text-primery-blue-900">
                        تفاصيل المرشح
                    </DialogTitle>
                </DialogHeader>
                {applicant ? (
                    <div className="space-y-3 text-right text-sm">
                        <div>
                            <span className="text-[#625E74]">الاسم</span>
                            <p className="font-medium text-[#111827]">{applicant.name}</p>
                        </div>
                        {(applicant.job?.title || applicant.job_title) && (
                            <div>
                                <span className="text-[#625E74]">الوظيفة</span>
                                <p className="font-medium text-[#111827]">
                                    {applicant.job?.title ?? applicant.job_title}
                                </p>
                            </div>
                        )}
                        {applicant.level ? (
                            <div>
                                <span className="text-[#625E74]">المستوى</span>
                                <p className="font-medium text-[#111827]">{applicant.level}</p>
                            </div>
                        ) : null}
                        {applicant.work_type ? (
                            <div>
                                <span className="text-[#625E74]">نوع العمل</span>
                                <p className="font-medium text-[#111827]">{applicant.work_type}</p>
                            </div>
                        ) : null}
                        {applicant.pipeline_stage ? (
                            <div>
                                <span className="text-[#625E74]">مرحلة المسار</span>
                                <p className="font-medium text-[#111827]">{applicant.pipeline_stage}</p>
                            </div>
                        ) : null}
                        {applicant.pipeline_started_at ? (
                            <div>
                                <span className="text-[#625E74]">تاريخ بدء المرحلة</span>
                                <p className="font-medium text-[#111827]">
                                    {formatDateTimeArEg(applicant.pipeline_started_at)}
                                </p>
                            </div>
                        ) : null}
                        {typeof applicant.skills === 'string' && applicant.skills.trim() ? (
                            <div>
                                <span className="text-[#625E74]">المهارات</span>
                                <p className="whitespace-pre-wrap text-[#111827]">{applicant.skills}</p>
                            </div>
                        ) : null}
                        {applicant.created_at ? (
                            <div>
                                <span className="text-[#625E74]">تاريخ التقديم</span>
                                <p className="font-medium text-[#111827]">{formatDateToArabic(applicant.created_at)}</p>
                            </div>
                        ) : null}
                        {applicant.notes?.trim() ? (
                            <div>
                                <span className="text-[#625E74]">ملاحظات المسار</span>
                                <div
                                    className="mt-1 max-h-40 overflow-y-auto rounded border border-[#E5E7EB] bg-[#FAFAFA] p-2 text-[#111827] quill-content"
                                    // eslint-disable-next-line react/no-danger
                                    dangerouslySetInnerHTML={{ __html: applicant.notes }}
                                />
                            </div>
                        ) : null}
                    </div>
                ) : null}
            </DialogContent>
        </Dialog>
    );
}
