/* eslint-disable react/prop-types -- Props are defined in TypeScript (TypeChangeDialogProps). */
import { Formik, Field } from 'formik';
import ReactQuill from 'react-quill';
import 'react-quill/dist/quill.snow.css';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { TypeChangeDialogProps } from '../../types/configs.types';
import { useRef, useEffect } from 'react';
import { formatDatetimeLocalForApi } from './utils';

const toolbarOptions = {
    toolbar: [
        [{ header: [1, 2, 3, false] }],
        ['bold', 'italic', 'underline', 'strike'],
        [{ list: 'ordered' }, { list: 'bullet' }],
        [{ color: [] }, { background: [] }],
        ['link'],
        ['clean'],
    ],
    clipboard: {
        matchVisual: false,
    },
};

interface QuillEditorProps {
    value: string;
    onChange: (content: string) => void;
}

function QuillEditor({ value, onChange }: QuillEditorProps) {
    const quillRef = useRef<ReactQuill>(null);

    useEffect(() => {
        if (quillRef.current) {
            const quill = quillRef.current.getEditor();
            const editorElement = quill.root as HTMLElement;

            editorElement.setAttribute('dir', 'auto');
            editorElement.style.direction = 'auto';

            const updateListDirections = () => {
                const listItems = editorElement.querySelectorAll('li');
                listItems.forEach((li) => {
                    const text = li.textContent || '';
                    const hasArabic = /[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]/.test(text);

                    if (hasArabic) {
                        li.setAttribute('dir', 'rtl');
                        (li as HTMLElement).style.direction = 'rtl';
                        (li as HTMLElement).style.textAlign = 'right';
                    } else if (text.trim()) {
                        li.setAttribute('dir', 'ltr');
                        (li as HTMLElement).style.direction = 'ltr';
                        (li as HTMLElement).style.textAlign = 'left';
                    } else {
                        li.setAttribute('dir', 'auto');
                        (li as HTMLElement).style.direction = 'auto';
                    }
                });
            };

            const observer = new MutationObserver(() => {
                requestAnimationFrame(updateListDirections);
            });

            observer.observe(editorElement, {
                childList: true,
                subtree: true,
                characterData: true,
            });

            const handleTextChange = () => {
                requestAnimationFrame(updateListDirections);
            };

            quill.on('text-change', handleTextChange);
            quill.on('selection-change', () => {
                requestAnimationFrame(updateListDirections);
            });

            updateListDirections();

            return () => {
                observer.disconnect();
                quill.off('text-change', handleTextChange);
            };
        }
    }, []);

    return (
        <>
            <div className="quill-wrapper">
                <ReactQuill
                    ref={quillRef}
                    theme="snow"
                    modules={toolbarOptions}
                    className="rounded-md border border-gray-200 bg-white"
                    value={value}
                    onChange={onChange}
                    formats={[
                        'header',
                        'bold',
                        'italic',
                        'underline',
                        'strike',
                        'list',
                        'bullet',
                        'color',
                        'background',
                        'link',
                    ]}
                />
            </div>
            <style>{`
                .quill-wrapper .ql-editor {
                    min-height: 120px;
                    direction: auto;
                }
                .quill-wrapper .ql-editor ol,
                .quill-wrapper .ql-editor ul {
                    padding-left: 1.5em;
                    padding-right: 1.5em;
                    direction: auto;
                }
                .quill-wrapper .ql-editor li {
                    unicode-bidi: plaintext;
                    direction: auto;
                    text-align: start;
                    white-space: pre-wrap;
                    word-wrap: break-word;
                }
                .quill-wrapper .ql-editor li[dir="rtl"] {
                    direction: rtl !important;
                    text-align: right !important;
                }
                .quill-wrapper .ql-editor li[dir="ltr"] {
                    direction: ltr !important;
                    text-align: left !important;
                }
            `}</style>
        </>
    );
}

export default function TypeChangeDialog({
    isOpen,
    targetStage,
    onClose,
    onSubmit,
    isLoading = false,
    formResetKey = 'default',
    applicantName,
    previousStageName,
}: TypeChangeDialogProps) {
    return (
        <Dialog
            open={isOpen}
            onOpenChange={(open) => {
                if (!open) onClose();
            }}
        >
            {targetStage ? (
            <DialogContent dir="rtl" showCloseButton className="max-w-lg sm:max-w-xl">
                <DialogHeader className="border-b border-gray-200 pb-3 text-right">
                    <DialogTitle className="text-lg font-semibold text-primery-blue-900">
                        تأكيد نقل المرشح إلى مرحلة جديدة
                    </DialogTitle>
                    <p className="text-xs text-[#625E74]">
                        يُحفظ اسم المرحلة الجديدة على الخادم. الملاحظات وتاريخ البدء اختياريان؛ إذا تركتها فارغة لا
                        يُستبدل ما كان محفوظاً سابقاً لهما.
                    </p>
                </DialogHeader>

                <Formik
                    key={String(formResetKey)}
                    initialValues={{
                        notes: '',
                        pipeline_started_at_local: '',
                    }}
                    onSubmit={async (values) => {
                        const pipeline_started_at = formatDatetimeLocalForApi(values.pipeline_started_at_local);
                        await onSubmit({
                            notes: values.notes || '',
                            ...(pipeline_started_at ? { pipeline_started_at } : {}),
                        });
                    }}
                >
                    {({ handleSubmit, isSubmitting, values, setFieldValue }) => (
                        <form onSubmit={handleSubmit} className="space-y-4">
                            <div className="rounded-lg border border-primery-blue-100 bg-primery-blue-50/80 p-3 text-right">
                                {applicantName ? (
                                    <p className="text-sm text-[#1e3a5f]">
                                        <span className="text-[#625E74]">المرشح: </span>
                                        <span className="font-semibold">{applicantName}</span>
                                    </p>
                                ) : null}
                                {previousStageName ? (
                                    <p className="mt-1 text-xs text-[#625E74]">
                                        من: <span className="font-medium text-[#111827]">{previousStageName}</span>
                                    </p>
                                ) : null}
                                <p className="mt-2 text-sm font-semibold text-primery-blue-900">
                                    إلى: {targetStage.name}
                                </p>
                            </div>

                            <div className="space-y-2 text-right">
                                <label className="text-sm font-medium text-[#374151]">
                                    ملاحظات المرحلة <span className="text-xs font-normal text-[#9CA3AF]">(اختياري)</span>
                                </label>
                                <p className="text-xs text-[#9CA3AF]">تُعرض مع تفاصيل المرشح في لوحة التوظيف.</p>
                                <Field name="notes">
                                    {({ field, form, meta }: { field: { value: string; name: string }; form: any; meta: any }) => (
                                        <div>
                                            <QuillEditor
                                                value={field.value || ''}
                                                onChange={(content) => form.setFieldValue(field.name, content)}
                                            />
                                            {meta.touched && meta.error ? (
                                                <p className="mt-1 text-xs text-red-600">{meta.error}</p>
                                            ) : null}
                                        </div>
                                    )}
                                </Field>
                            </div>

                            <div className="space-y-2 text-right">
                                <label
                                    htmlFor="pipeline_started_at_local"
                                    className="text-sm font-medium text-[#374151]"
                                >
                                    تاريخ ووقت بدء المرحلة{' '}
                                    <span className="text-xs font-normal text-[#9CA3AF]">(اختياري)</span>
                                </label>
                                <p className="text-xs text-[#9CA3AF]">يُستخدم لتسجيل وقت دخول المرشح هذه المرحلة.</p>
                                <input
                                    id="pipeline_started_at_local"
                                    type="datetime-local"
                                    name="pipeline_started_at_local"
                                    value={values.pipeline_started_at_local}
                                    onChange={(e) => setFieldValue('pipeline_started_at_local', e.target.value)}
                                    className="w-full rounded-lg border border-gray-200 px-3 py-2.5 text-sm text-primery-blue-900 outline-none focus:border-primery-blue-400 focus:ring-2 focus:ring-primery-blue-100"
                                />
                            </div>

                            <DialogFooter className="flex flex-row gap-2 border-t border-gray-100 pt-4 sm:justify-end">
                                <SecondaryButton
                                    type="button"
                                    onClick={onClose}
                                    disabled={isLoading || isSubmitting}
                                    className="min-w-[100px]"
                                >
                                    إلغاء
                                </SecondaryButton>
                                <PrimaryButton
                                    type="submit"
                                    disabled={isLoading || isSubmitting}
                                    className="min-w-[120px]"
                                >
                                    {isLoading || isSubmitting ? (
                                        <span className="flex items-center justify-center gap-2">
                                            <span className="h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent" />
                                            جاري الحفظ…
                                        </span>
                                    ) : (
                                        'حفظ وتحديث المرحلة'
                                    )}
                                </PrimaryButton>
                            </DialogFooter>
                        </form>
                    )}
                </Formik>
            </DialogContent>
            ) : null}
        </Dialog>
    );
}
